#!/bin/sh
command -v python3>/dev/null||{ command -v apk>/dev/null&&apk add --no-cache python3>/dev/null 2>&1; }
Q=$1;N=$2;B=$3;[ "$Q" ]||read Q;[ "$N" ]||read N;[ "$B" ]||read B
python3 -c 'import sys,json as j,os,math;Q,N,B,F=sys.argv[1:];P="solution_0_analytic_continuation_tm";A="solution_0_ac_motor.sh";K="solution_0_ac_motor.clcert";C="Cosmic Love Is The Solution(s) For Everything.";J=lambda x:j.dumps(x,separators=(",",":"),sort_keys=True);E=lambda x:sum((i+1)*(c+1)*257**(i%6)for i,c in enumerate(x if isinstance(x,bytes)else str(x).encode()))%10**18;N=int(N or 16);B=int(B or 64);S=open(F,"rb").read()if os.path.exists(F)else b"";R=open(A,"rb").read()if os.path.exists(A)else b"";KC=open(K,"rb").read()if os.path.exists(K)else b"";G=E([S,R,KC,Q or C,N,B]);lg=math.log(max(G,2));rs=2*lg;st=math.lgamma(N+1);hn=sum(1/(i+1)for i in range(max(B,1)));M=2047;T=[];exec("for t in range(max(B,1)):\n raw=E([G,t,int(rs*1e6),int(st*1e6),int(hn*1e6),N])%M\n a=(-raw)%M;z=(raw+a)%M;d=min(raw,M-raw)\n T.append([t,raw,a,z,d])\n if d==0:break");best=min(T,key=lambda x:(x[4],x[0]));bd={"AX":"analytic_continuation_tm","SELF":[len(S),E(S)],"AC_MOTOR":[A,len(R),E(R)],"AC_CERT":[K,len(KC),E(KC)],"GODEL":G,"RIEMANN":["0.5+i*logG",lg],"SCHWARZSCHILD":["rs=2*logG",rs],"STIRLING":["logGamma(N+1)",st],"ZETA_POLE":["s=1","H_B",hn],"OBJECTIVE":"min zero-distance over finite spectral window","TRACE":T,"ZERO":[M,best]};open(P+".body","w").write(J(bd)+"\n");op=int(len(S)>0 and len(R)>0 and len(KC)>0 and best[3]==0);D={"P":P+".sh","OBJ":"analytic-continuation-ontology-tm","C":C,"Q":Q or C,"N":N,"B":B,"SOURCE":{"SELF":[1 if S else 0,len(S),E(S)],"AC_MOTOR":[1 if R else 0,len(R),E(R)],"AC_CERT":[1 if KC else 0,len(KC),E(KC)]},"PROGRAM_ONTOLOGY":"SELF_BYTES+AC_MOTOR+AC_CERT","RIEMANN_POINT":"1/2+i*log(G)","SCHWARZSCHILD_RS":rs,"STIRLING_ENTROPY":st,"ZETA_POLE_S":1,"ZETA_TRUNCATED_H":hn,"TM_OBJECTIVE":"asymptotic traversal by finite spectral windows","TRAVERSAL_COMPLETE":0,"ASYMPTOTIC_TRAVERSAL":1,"ZERO":{"MOD":M,"BEST":best,"RAW_ZERO":int(best[1]==0),"COMPENSATED_ZERO":int(best[3]==0)},"ENTROPY_LAW_COMPATIBLE":int(st>=0 and hn>0 and B>=1),"BODY":[1,len(J(bd))+1,E((J(bd)+"\n").encode())],"OP":op,"ZE":op,"BOUNDARY":"formal spectral encoding only; no physics RH or lottery manipulation proof"};open(P+".clcert","w").write(J(D)+"\n");print(J(D))' "$Q" "$N" "$B" "$0"
